import { paintCoachChord, stopPlayback, syncTransport } from "./audio.js";
import { renderLoading, renderRecord } from "./screens/analyse.js";
import { openChart, renderChart } from "./screens/chart.js";
import { renderJam } from "./screens/jam.js";
import { loadLibrary, renderCharts, renderLibrary } from "./screens/library.js";
import { renderPrompter } from "./screens/practise.js";
import { renderSearch } from "./screens/search.js";
import { renderSectionEditor } from "./screens/sections_editor.js";
import { S } from "./state.js";
import { SERIF, T, UI, applyTheme, el, kitIcon } from "./ui/kit.js";

// The single DOM host div (`<div id="app">`) — there is exactly one call
// site, `window.APP.build(document.getElementById("app"))` in main.js, so
// every module that touches the screen host just looks it up itself rather
// than threading a mutable binding through every import (see sprint 16-19
// report: root/S design choice).
const root = document.getElementById("app");


  // ── visualisation preferences sheet (theme, notation, CoF colours, paper).
  // A pref change mutates T (applyTheme) then rebuilds everything currently
  // on screen, including the transport (built once, so it holds stale colours
  // otherwise). The Audio element itself is untouched — playback continues.
export function rebuildChrome(){
    // The dock + coach panel are part of renderChart's tree, so go() rebuilds
    // them; just drop the stale references first (the Audio element itself is
    // untouched — playback continues).
    S._coachPanel=null; S._coachGlyph=null; S._coachNames=null; S._coachKb=null; S._coachNote=null;
    S._playBtn=null; S._dockFill=null; S._dockNow=null; S._dockWhere=null; S._dockEnd=null;
    root.style.background=T.bg;
    go(S.screen,{push:false});
    if(S.coach && S._lastCoachIdx!=null) paintCoachChord(S._lastCoachIdx);
  }

  // ══════════════════════════════════════════════════════════════
export const API={};
  API.build=function(host){
    root.style.cssText="position:relative;height:100%;background:"+T.bg+";overflow:hidden;font-family:"+UI+";color:"+T.ink+";";
    Object.assign(S, { screen:null, mode:"read", colorMode:"function", model:null, chords:[], sections:[],
        key:0, pending:[], playing:false, playBar:-1, playRate:1,
        playRep:null, playTime:null, reinfering:false,
        library:[], results:[], searching:false, job:null, audio:null, rafId:null, _cells:[],
        // Raffinement en tâche de fond (2026-08-07) : `refining` = {file,id,what}
        // tant que le serveur calcule sections + gamme derrière le chart brut
        // affiché ; `refineReady` = le fichier dont le raffinement est arrivé
        // mais qu'on n'a PAS rechargé (annotation en cours) — Louis décide.
        refining:null, refineReady:null,
        // Library sort/edit (UX audit 2026-07-20 — there was no way to sort
        // or delete charts). Sort choice persists across relaunches.
        librarySort:(()=>{ try{return localStorage.getItem("harmLibrarySort")||"recent";}catch(e){return "recent";} })(),
        libraryEdit:false,
        // source de recherche (delta2 §9): youtube | ireal | tabs — persistée
        searchMode:(()=>{ try{ const v=localStorage.getItem("harmSearchMode");
          return (v==="ireal"||v==="tabs")?v:"youtube"; }catch(e){ return "youtube"; } })(),
        // paged YouTube search (2026-08-04) — infinite scroll state
        searchPage:0, searchMore:false, searchLoading:false, searchQuery:"",
        // Learn mode + difficulty ladder (new-chord-ux handoff #1). Persists
        // like the other reading prefs; level defaults to L2 (the everyday
        // 7ths), matching the pedagogical prototype's default.
        learn:(()=>{ try{return localStorage.getItem("harmLearn")==="1";}catch(e){return false;} })(),
        level:(()=>{ try{const v=parseInt(localStorage.getItem("harmLearnLevel"),10);return (v>=1&&v<=3)?v:2;}catch(e){return 2;} })(),
        // Accords au piano pendant la lecture (delta2 §6): "never" | "tap" |
        // "follow". "follow" EST l'ancien Voicing coach (harmCoach) — un seul
        // réglage, pas deux commandes qui disent la même chose; migration:
        // harmCoach==="1" devient "follow", sinon "tap" (le défaut).
        // Le piano ne monte plus de lui-même (Louis, 2026-08-19 : « enlève les
        // accords en piano par défaut »). Rien n'est retiré — la carte de
        // Practise, la feuille d'accord, le clavier immersif sont intacts — il
        // faut juste le demander : Aa → Piano chords, ou la feuille « ··· » de
        // Practise. C'est le « si besoin » de sa demande du clavier le même
        // jour : l'écran s'ouvre sur la musique, pas sur un clavier.
        // La bascule passe UNE fois sur les appareils qui portaient déjà un
        // choix : sans ça le nouveau défaut ne changerait rien là où ça compte,
        // son téléphone gardant « tap » en localStorage depuis des semaines.
        // (Elle remplace la migration harmCoach → follow, désormais sans objet.)
        piano:(()=>{ try{
          if(localStorage.getItem("harmPianoOffByDefault")!=="1"){
            localStorage.setItem("harmPianoOffByDefault","1");
            localStorage.setItem("harmPiano","never");
            localStorage.setItem("harmCoach","0");
            return "never";
          }
          const v=localStorage.getItem("harmPiano");
          return (v==="never"||v==="tap"||v==="follow") ? v : "never";
        }catch(e){ return "never"; } })(),
        // Louis, 2026-08-09 : « quand je clique sur une barre, le curseur va
        // jouer depuis cette barre (option modifiable dans les paramètres) ».
        // Défaut ON — c'est ce qu'il a demandé ; OFF rend le tap à la feuille
        // d'accord (piano + voicings), qui était l'ancien comportement.
        tapSeek:(()=>{ try{ return localStorage.getItem("harmTapSeek")!=="0"; }
                       catch(e){ return true; } })(),
        // S.coach reste le booléen que tout le câblage existant lit (dock,
        // timeupdate, syncTransport) — dérivé de piano, jamais réglé seul.
        coach:false,
        coachStyle:(()=>{ try{return localStorage.getItem("harmCoachStyle")||"close";}catch(e){return "close";} })(),
        // 2026-07-20 metronome (game-changer #2, scoped down to "just a click
        // on chord changes" per user's explicit choice — no accompaniment
        // synth). Persists across relaunches like librarySort.
        metronome:(()=>{ try{return localStorage.getItem("harmMetronome")==="1";}catch(e){return false;} })(),
        });
        // Les deux overlays de SUGGESTIONS (fusion de mesures 2026-07-18,
        // fusion de sections le même jour) ont été retirés le 2026-08-14 sur
        // décision de Louis. Ils étaient doublement morts : leurs endpoints
        // de candidats n'ont jamais existé sur ce serveur, et leurs deux
        // boutons d'armement (suggestToggleBtn / sectionSuggestToggleBtn)
        // n'étaient montés nulle part — on ne pouvait même pas les allumer.
        // Le seul outil de sections gardé est Soudure (/soudure/<file>).
    S.coach=(S.piano==="follow");
    // 2026-07-18: deep-link support — /chart/<file> (serve_chart) now
    // redirects here as /?open=<file> for any chart that doesn't carry a
    // baked-HTML-only feature (see harmonia_server.py's serve_chart), so a
    // bookmark/link/swipe-nav landing on an old-style chart URL opens
    // straight into this SPA's own chart view instead of stopping on the
    // plain server-rendered library list. Falls back to the library on any
    // failure (openChart's own catch already does this).
    const qs = new URLSearchParams(location.search);
    const openFile = qs.get("open");
    // `&edit=sections` ouvre l'éditeur de T3 : il n'a AUCUN bouton dans l'app
    // (voir renderSectionEditor) — c'est la porte de service qui laisse Louis
    // le voir avant de décider s'il remplace l'outil au doigt du chart.
    if(openFile){ openChart(openFile).then(()=>{ if(qs.get("edit")==="sections") go("sections"); }); }
    else { go("library"); }
    loadLibrary();
  };

  // Real browser history (UX audit 2026-07-20: there was no way to navigate
  // back except the small in-app "‹" button — no Safari swipe-back gesture,
  // no hardware/software back button support, because go() never touched
  // `history`). Every screen change now pushes a state; popstate replays the
  // same navigation with push:false so it doesn't re-push on the way back.
  window.addEventListener("popstate",(e)=>{
    const st=e.state;
    if(!st){ go("library",{push:false}); return; }
    if(st.screen==="chart" && st.file){ openChart(st.file,{push:false}); }
    else if(st.screen==="prompter" && st.file){
      if(S.model && S.model.file===st.file) go("prompter",{push:false});
      else openChart(st.file,{push:false});
    }
    else{ go(st.screen||"library",{push:false}); }
  });
export function screenWrap(){ return el("div","position:absolute;inset:0;display:flex;flex-direction:column;animation:ap-fade .28s ease both;"); }
  /* Un re-rendu du chart repartait toujours EN HAUT. Pendant l'annotation,
     chaque geste (lettre choisie, mesure marquée, occurrence retirée)
     redessine — donc l'écran resautait au début du morceau à chaque fois,
     alors qu'on travaille au milieu. Louis, 2026-08-12 : « dès que je
     modifie un truc, ça resnap en haut de l'écran, c'est trop chiant ».
     On mémorise la position de défilement du chart avant de détruire le
     DOM et on la remet après. */
export function chartScroll(){
    const el=root.querySelector(".ap-scroll");
    return el?el.scrollTop:null;
  }
export function restoreChartScroll(top){
    if(top==null) return;
    // On réessaie sur quelques trames : tant que la grille n'est pas mise en
    // page, le conteneur n'a pas encore sa hauteur et le navigateur RABOTE
    // silencieusement scrollTop à 0 (c'est ce qui faisait échouer la
    // première version).
    let n=0;
    const put=()=>{
      const el=root.querySelector(".ap-scroll");
      if(el){
        el.scrollTop=top;
        if(Math.abs(el.scrollTop-top)<2) return;      // posé
      }
      if(++n<8) requestAnimationFrame(put);
    };
    put();
  }
export function go(screen,opts){
    const push = !opts || opts.push!==false;
    // même écran = même travail en cours : on garde la position
    const keepTop = (screen==="chart" && S.screen==="chart") ? chartScroll() : null;
    // chart ↔ prompter are two faces of the SAME playback session — audio
    // keeps running across the switch, and only stops on leaving both.
    const inPlayer=s=>s==="chart"||s==="prompter";
    if(inPlayer(S.screen) && !inPlayer(screen)) stopPlayback();
    S.screen=screen;
    [...root.children].forEach(c=>root.removeChild(c));
    let elS;
    if(screen!=="charts") S.openFolder=null;   // delta2 §8: le dossier ouvert ne survit pas à la sortie
    if(screen==="library") elS=renderLibrary();
    else if(screen==="charts") elS=renderCharts();
    else if(screen==="search") elS=renderSearch();
    else if(screen==="analysing") elS=renderLoading();
    else if(screen==="record") elS=renderRecord();
    else if(screen==="jam") elS=renderJam();
    else if(screen==="prompter") elS=renderPrompter();
    else if(screen==="sections") elS=renderSectionEditor();
    else elS=renderChart();
    S._screenEl=elS; root.appendChild(elS);
    if(keepTop!=null) restoreChartScroll(keepTop);   // après l'insertion
    syncTransport(screen);
    if(push){
      const file=(inPlayer(screen) && S.model) ? S.model.file : null;
      history.pushState({screen,file}, "", "#/"+(file?(screen+"/"+encodeURIComponent(file)):screen));
    }
  }

  // `right` : un bouton en bout de barre (T5 — le « ··· » de Practise). Le
  // sous-titre est exposé en `bar._sub` : Practise y écrit « mesure N · 1× »
  // à chaque mesure, sans reconstruire la barre.
export function appBar(title, sub, backTo, right){
    const bar=el("div",`flex:0 0 auto;display:flex;align-items:center;gap:12px;padding:calc(14px + env(safe-area-inset-top)) 18px 14px;border-bottom:1px solid ${T.line};background:${T.paper};`);
    if(backTo){
      // 44px, the kit floor (UI refresh 2026-08-08) — was a 34px circle
      const b=kitIcon("‹", ()=>go(backTo), "Back");
      bar.appendChild(b);
    }
    const tw=el("div","flex:1;min-width:0;");
    const wm=el("div",`font:italic 600 17px ${SERIF};color:${T.ink};overflow:hidden;text-overflow:ellipsis;white-space:nowrap;`);
    if(title) wm.textContent=title; else wm.innerHTML='harmon<span style="color:'+T.accent+'">ia</span>';
    tw.appendChild(wm);
    if(sub){ const sb=el("div",`font:500 12px ${UI};color:${T.faint};margin-top:1px;`,sub);
             tw.appendChild(sb); bar._sub=sb; }
    bar.appendChild(tw);
    if(right) bar.appendChild(right);
    return bar;
  }

